        // post.local_reads[r] == pre.local_reads[r]
        // And pre.inv_readonly_requests_wf holds.
        // We need to show post.wf_readstate(post.local_reads[rid]) for the new Done state.
    }

    // Show inv_read_results (the Done state's result matches)
    assert(post.inv_read_results()) by {
        // For r != rid: post.local_reads[r] == pre.local_reads[r], and pre.inv_read_results holds
        // For r == rid: post.local_reads[rid] = Done { op, node_id, version_upper_bound, ret }
        // where ret = DT::dispatch_spec(state, op) and state = pre.replicas[node_id]

        // We need to show: exists |v| rangeincl(version_upper_bound, v, post.version_upper_bound)
        //     && ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)

        // From the transition:
        let old_readstate = pre.local_reads[rid];
        match old_readstate {
            ReadonlyState::ReadyToRead { op, node_id, version_upper_bound } => {
                // From pre.inv_readonly_requests_wf and ReadyToRead state:
                // version_upper_bound <= pre.current_local_version(node_id)
                // And from inv_local_version_upper_bound_heads:
                // pre.current_local_version(node_id) <= version_upper_bound
                // So: pre.current_local_version(node_id) == version_upper_bound

                // From pre.replica_state:
                // pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id))
                // == compute_nrstate_at_version(pre.log, version_upper_bound)

                // Since readonly_apply doesn't change log:
                // pre.log === post.log
                // So: state == compute_nrstate_at_version(post.log, version_upper_bound)

                // And: ret == DT::dispatch_spec(state, op)
