fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    // readonly_apply changes only local_reads[rid] from ReadyToRead to Done
    // All other state fields are unchanged

    // Prove post.invariant()

    // Get the old read state
    let old_readstate = pre.local_reads[rid];
    match old_readstate {
        ReadonlyState::ReadyToRead { op, node_id, version_upper_bound } => {
            // Continue with the proof
            let state = pre.replicas[node_id];
            let ret = DT::dispatch_spec(state, op);

            // From pre.inv_readonly_requests_wf:
            assert(pre.wf_readstate(old_readstate));

            // For all r != rid, post.local_reads[r] == pre.local_reads[r]
            // and pre.invariant implies post.invariant for those r

            // For r == rid, post.local_reads[rid] = Done { op, node_id, version_upper_bound, ret }
            // Need to show: post.read_results_match(Done)
            // i.e., exists |v| rangeincl(version_upper_bound, v, post.version_upper_bound)
            //            && ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)

            // From pre.replica_state (invariant in pre):
            assert(pre.replica_state());
            // Therefore: pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id))

            // From wf_readstate(ReadyToRead) in pre:
            //   version_upper_bound <= pre.current_local_version(node_id)
            // From inv_local_version_upper_bound_heads (invariant in pre):
            //   pre.current_local_version(node_id) <= pre.version_upper_bound == version_upper_bound
            // So: pre.current_local_version(node_id) == version_upper_bound

            // Therefore: pre.replicas[node_id] == compute_nrstate_at_version(pre.log, version_upper_bound)
            // And since readonly_apply doesn't change log:
            //   pre.log === post.log (all entries equal)
            // So: pre.replicas[node_id] == compute_nrstate_at_version(post.log, version_upper_bound)

            // And: ret == DT::dispatch_spec(pre.replicas[node_id], op)
            // So: ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, version_upper_bound), op)

            // Also: post.version_upper_bound == version_upper_bound (unchanged by transition)
            // So: rangeincl(version_upper_bound, version_upper_bound, post.version_upper_bound)
            //     == (version_upper_bound <= version_upper_bound && version_upper_bound <= version_upper_bound)
