            //   pre.wf_node_id(node_id)
            // Since other fields unchanged:
            //   post.current_local_version(node_id) == pre.current_local_version(node_id)
            //   post.version_upper_bound == pre.version_upper_bound == version_upper_bound
            // So: version_upper_bound <= post.version_upper_bound
            //     version_upper_bound <= post.current_local_version(node_id)
            //   post.wf_node_id(node_id)
            // Therefore: post.wf_readstate(Done)
